<?php
require_once __DIR__ . '/layout.php';
medical_require_permission('view');
if(!medical_schema_ready()){header('Location:index.php');exit;}
$id=(int)(isset($_GET['id'])?$_GET['id']:0);$row=medical_get_request($id);if(!$row||!medical_can_view_request($row)){http_response_code(404);die('ไม่พบรายการหรือไม่มีสิทธิ์ดูข้อมูล');}
$u=medical_current_user();$sm=medical_status_meta($row['status']);$pm=medical_priority_meta($row['priority']);
$technicians=array();$rs=$conn->query("SELECT id,fullname,specialty FROM medical_technicians WHERE status='active' ORDER BY fullname");if($rs)while($x=$rs->fetch_assoc())$technicians[]=$x;
$logs=array();$stmt=$conn->prepare("SELECT l.*,u.fullname actor_name FROM medical_status_logs l LEFT JOIN users u ON u.id=l.user_id WHERE l.request_id=? ORDER BY l.id DESC");if($stmt){$stmt->bind_param('i',$id);$stmt->execute();$res=$stmt->get_result();if($res)while($x=$res->fetch_assoc())$logs[]=$x;$stmt->close();}
$feedback=null;$stmt=$conn->prepare("SELECT * FROM medical_feedback WHERE request_id=? LIMIT 1");if($stmt){$stmt->bind_param('i',$id);$stmt->execute();$res=$stmt->get_result();if($res)$feedback=$res->fetch_assoc();$stmt->close();}
medical_page_start('รายละเอียดงานแจ้งซ่อม '.$row['request_no'],'ตรวจสอบข้อมูลเครื่องมือ การมอบหมายช่าง สถานะ และผลการดำเนินงาน','dashboard');
?>
