<div class="med-info-grid"><div><span>ผู้แจ้ง</span><strong><?= medical_e($row['requester_name']) ?></strong></div><div><span>หน่วยงาน</span><strong><?= medical_e($row['department']) ?></strong></div><div><span>เบอร์ติดต่อ</span><strong><?= medical_e($row['contact_phone']?:'-') ?></strong></div><div><span>สถานที่</span><strong><?= medical_e($row['location']) ?></strong></div><div><span>ชื่อเครื่องมือ</span><strong><?= medical_e($row['equipment_name']) ?></strong></div><div><span>เลขครุภัณฑ์</span><strong><?= medical_e($row['asset_code']?:'-') ?></strong></div><div><span>ประเภท</span><strong><?= medical_e($row['category']?:'-') ?></strong></div><div><span>ยี่ห้อ / รุ่น</span><strong><?= medical_e(trim($row['brand'].' '.$row['model'])?:'-') ?></strong></div><div><span>Serial Number</span><strong><?= medical_e($row['serial_no']?:'-') ?></strong></div><div><span>ประเภทปัญหา</span><strong><?= medical_e(medical_problem_meta($row['problem_type'])) ?></strong></div></div>
<div class="med-note"><span>รายละเอียดอาการ / ปัญหา</span><?= nl2br(medical_e($row['problem_detail'])) ?></div>
<div class="med-note"><span>ผลการตรวจสอบ / การแก้ไข</span><?= $row['resolution']?nl2br(medical_e($row['resolution'])):'<em>ยังไม่มีข้อมูล</em>' ?></div>
<div class="med-info-grid"><div><span>ช่างผู้รับผิดชอบ</span><strong><?= medical_e($row['technician_name']?:'ยังไม่มอบหมาย') ?></strong></div><div><span>ค่าใช้จ่าย</span><strong><?= number_format((float)$row['cost'],2) ?> บาท</strong></div><div><span>รับงานเมื่อ</span><strong><?= medical_thai_datetime($row['accepted_at']) ?></strong></div><div><span>เสร็จสิ้นเมื่อ</span><strong><?= medical_thai_datetime($row['completed_at']) ?></strong></div></div>
