</section>
<aside>
<?php if(medical_can('manage')): ?><section class="med-card med-side"><h3>จัดการสถานะงาน</h3><form method="post" action="status_update.php"><input type="hidden" name="csrf_token" value="<?= medical_e(medical_csrf_token()) ?>"><input type="hidden" name="id" value="<?= $id ?>"><label>สถานะ</label><select name="status" required><?php foreach(array('pending'=>'รอตรวจสอบ','assigned'=>'มอบหมายแล้ว','in_progress'=>'กำลังซ่อม','waiting_parts'=>'รออะไหล่','completed'=>'เสร็จสิ้น','cancelled'=>'ยกเลิก') as $v=>$l): ?><option value="<?= $v ?>" <?= $row['status']===$v?'selected':'' ?>><?= $l ?></option><?php endforeach; ?></select><label>ช่างผู้รับผิดชอบ</label><select name="technician_id"><option value="0">-- ยังไม่มอบหมาย --</option><?php foreach($technicians as $t): ?><option value="<?= (int)$t['id'] ?>" <?= (int)$row['technician_id']===(int)$t['id']?'selected':'' ?>><?= medical_e($t['fullname']) ?><?= $t['specialty']?' — '.medical_e($t['specialty']):'' ?></option><?php endforeach; ?></select><label>หมายเหตุช่าง</label><textarea name="technician_note" placeholder="ผลการตรวจสอบ หรือสถานะล่าสุด"><?= medical_e($row['technician_note']) ?></textarea><label>ผลการซ่อม / วิธีแก้ไข</label><textarea name="resolution" placeholder="บันทึกวิธีแก้ไข อะไหล่ที่เปลี่ยน และผลทดสอบ"><?= medical_e($row['resolution']) ?></textarea><label>ค่าใช้จ่าย (บาท)</label><input type="number" step="0.01" min="0" name="cost" value="<?= medical_e($row['cost']) ?>"><button class="med-btn med-btn-primary med-block">บันทึกสถานะและแจ้ง LINE</button></form></section><?php endif; ?>
<?php if($row['status']==='completed' && (int)$row['user_id']===(int)$u['id']): ?><section class="med-card med-side"><h3>ประเมินความพึงพอใจ</h3><form method="post" action="feedback_save.php"><input type="hidden" name="csrf_token" value="<?= medical_e(medical_csrf_token()) ?>"><input type="hidden" name="id" value="<?= $id ?>"><div class="med-rating"><label><input type="radio" name="rating" value="5" <?= $feedback&&(int)$feedback['rating']===5?'checked':'' ?> required><span>5<small>ดีมาก</small></span></label><label><input type="radio" name="rating" value="3" <?= $feedback&&(int)$feedback['rating']===3?'checked':'' ?>><span>3<small>พอใช้</small></span></label><label><input type="radio" name="rating" value="1" <?= $feedback&&(int)$feedback['rating']===1?'checked':'' ?>><span>1<small>ปรับปรุง</small></span></label></div><textarea name="comment" placeholder="ความคิดเห็นเพิ่มเติม"><?= medical_e($feedback?$feedback['comment']:'') ?></textarea><button class="med-btn med-btn-primary med-block">บันทึกการประเมิน</button></form></section><?php endif; ?>
<section class="med-card med-side"><h3>ประวัติการดำเนินงาน</h3><div class="med-timeline"><?php if(!$logs): ?><p>ยังไม่มีประวัติ</p><?php endif; ?><?php foreach($logs as $l): ?><div><i></i><strong><?= medical_e($l['actor_name']?:'ระบบ') ?></strong><span><?= medical_e($l['note']?:$l['action_key']) ?></span><small><?= medical_thai_datetime($l['created_at']) ?></small></div><?php endforeach; ?></div></section>
</aside></div>
